<title>The Input Mode Observatory</title>
<style>
:root{--ink:#101722;--paper:#ead9b4;--paper2:#cbae78;--brass:#d3a63b;--red:#9e382c;--blue:#7fabc0;--cream:#fff3d4;--muted:#a7a28f;--shadow:#05080c}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--cream);background:var(--ink);font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;font-size:18px;overflow-x:hidden}
body:before{content:"";position:fixed;inset:0;pointer-events:none;z-index:20;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E")}
a{color:inherit}.mast{min-height:100svh;display:grid;place-items:center;position:relative;padding:24px 20px 50px;background:radial-gradient(circle at 50% 35%,#26394b 0,#111a26 43%,#080c12 100%)}
.mast:after{content:"";position:absolute;left:50%;bottom:0;width:1px;height:70px;background:linear-gradient(transparent,var(--brass))}
.hero{width:min(1050px,100%);text-align:center;position:relative;z-index:1}.eyebrow,.label{font-family:"Franklin Gothic Condensed","Arial Narrow",sans-serif;letter-spacing:.18em;text-transform:uppercase;font-size:.72rem;color:var(--brass)}
h1{font-size:clamp(3.4rem,10vw,7.7rem);line-height:.8;letter-spacing:-.045em;margin:.24em 0 .18em;font-weight:500;text-wrap:balance}.roman{font-style:italic;color:var(--paper);display:block;font-size:.52em;letter-spacing:.01em;margin-top:.14em}
.deck{max-width:610px;margin:0 auto 28px;color:#c8c5b8;font-size:clamp(1.08rem,2vw,1.35rem);line-height:1.45}.apparatus{display:block;width:100%;aspect-ratio:3/2;object-fit:cover;border:1px solid #856b38;box-shadow:0 30px 80px #000b,0 0 0 7px #131216,0 0 0 8px #6c5226;filter:saturate(.86) contrast(1.06);clip-path:polygon(2% 0,98% 0,100% 5%,100% 95%,98% 100%,2% 100%,0 95%,0 5%)}
.hero-actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:-27px;position:relative}.btn{border:1px solid #e5bd5b;background:var(--brass);color:#171109;font:600 .82rem "Franklin Gothic Condensed","Arial Narrow",sans-serif;text-transform:uppercase;letter-spacing:.1em;padding:14px 21px;cursor:pointer;box-shadow:4px 5px 0 #05080c;transition:.18s transform,.18s background}.btn:hover{background:#efc95e;transform:translateY(-2px)}.btn.secondary{background:#151b23;color:var(--paper)}
main{width:min(860px,calc(100% - 32px));margin:0 auto;padding:95px 0 80px}.intro{display:grid;grid-template-columns:1fr 1.7fr;gap:45px;align-items:start;margin-bottom:60px}.intro h2{font-size:clamp(2.3rem,6vw,4.2rem);line-height:.94;font-weight:500;margin:.1em 0}.intro p{color:#bbb8aa;line-height:1.65;margin:.2em 0}.rule{height:1px;background:linear-gradient(90deg,var(--brass),transparent);margin:18px 0}
.chamber{border:1px solid #806b42;background:linear-gradient(145deg,#171c23,#0b1017);box-shadow:0 20px 60px #0007;padding:clamp(20px,5vw,50px);position:relative;overflow:hidden}.chamber:before{content:"I · II";position:absolute;right:-10px;top:-40px;font-size:9rem;color:#fff;opacity:.025}.stepno{font:500 .75rem "Franklin Gothic Condensed","Arial Narrow",sans-serif;letter-spacing:.16em;color:var(--brass);text-transform:uppercase}.chamber h2{font-size:clamp(2rem,5vw,3.1rem);font-weight:500;margin:.15em 0 .3em}.chamber p{color:#c1bdad;line-height:1.55}.name-row{display:grid;grid-template-columns:1fr auto;gap:10px;margin-top:25px}.name-row input{min-width:0;background:#080d13;border:1px solid #665a40;color:var(--cream);padding:13px 15px;font:1rem "Iowan Old Style","Palatino Linotype",Palatino,serif;outline:none}.name-row input:focus{border-color:var(--brass)}
.progress{display:flex;gap:7px;margin:0 0 28px}.pip{height:4px;flex:1;background:#343943}.pip.on{background:var(--brass);box-shadow:0 0 13px #d3a63b88}
.mode-badge{display:inline-flex;align-items:center;gap:9px;border:1px solid #6a5d40;border-radius:30px;padding:7px 13px;font:500 .72rem "Franklin Gothic Condensed","Arial Narrow",sans-serif;letter-spacing:.13em;text-transform:uppercase;color:var(--paper)}.mode-badge i{width:8px;height:8px;border-radius:50%;background:var(--red);box-shadow:0 0 12px var(--red)}
.passage{font-size:clamp(1.2rem,3vw,1.52rem);line-height:1.62;background:#e7d4aa;color:#292016;padding:clamp(22px,5vw,42px);border:7px solid #ae8a4f;box-shadow:inset 0 0 40px #8a642c44;margin:22px 0;max-height:400px;overflow:auto}.passage:first-letter{font-size:3.5em;float:left;line-height:.72;margin:.1em .08em 0 0;color:var(--red)}
.listen-box{display:grid;place-items:center;min-height:260px;margin:22px 0;border:1px solid #6a5633;background:radial-gradient(circle,#2b2630,#0a1017 68%)}.disc{width:150px;aspect-ratio:1;border-radius:50%;background:repeating-radial-gradient(circle,#17191b 0 3px,#343233 4px 5px);border:5px solid #08090a;display:grid;place-items:center;box-shadow:0 15px 25px #0008;animation:spin 4s linear infinite;animation-play-state:paused}.disc.playing{animation-play-state:running}.disc:after{content:"LISTEN";display:grid;place-items:center;width:56px;aspect-ratio:1;border-radius:50%;background:var(--red);font:500 .62rem "Franklin Gothic Condensed","Arial Narrow",sans-serif;letter-spacing:.1em}.listen-box.speaking .disc{animation-play-state:running}@keyframes spin{to{transform:rotate(360deg)}}
.question{border-top:1px solid #3e4245;padding:18px 0}.question strong{display:block;font-weight:500;margin-bottom:10px}.options{display:grid;grid-template-columns:1fr 1fr;gap:8px}.option{background:#111821;border:1px solid #424743;color:#d5d1c4;text-align:left;padding:11px 12px;font:1rem "Iowan Old Style","Palatino Linotype",Palatino,serif;cursor:pointer}.option:hover,.option.selected{border-color:var(--brass);color:#fff}.option.selected{background:#352b1b}.confidence{margin:25px 0}.confidence input{width:100%;accent-color:var(--brass)}
.result-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:25px 0}.meter-card{background:#0b1016;border:1px solid #4e493b;padding:20px}.meter-card h3{font:500 .76rem "Franklin Gothic Condensed","Arial Narrow",sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--paper);margin:0}.score{font-size:4rem;line-height:1;color:var(--brass);margin:.16em 0}.bar{height:7px;background:#30343a}.bar span{display:block;height:100%;background:linear-gradient(90deg,var(--red),var(--brass));width:0;transition:width 1s ease}.verdict{border-left:4px solid var(--red);padding:15px 20px;background:#241b1c;font-size:1.2rem}.hidden{display:none!important}.tiny{font:400 .72rem "Franklin Gothic Condensed","Arial Narrow",sans-serif;letter-spacing:.08em;color:#868578}.source{text-align:center;margin-top:55px;color:#858477;font-size:.92rem}.source a{color:var(--paper);text-decoration-color:var(--red);text-underline-offset:4px}.reset{margin-top:14px}
@media(max-width:650px){.mast{padding-left:15px;padding-right:15px}.intro{grid-template-columns:1fr;gap:10px}.options,.result-grid{grid-template-columns:1fr}.chamber{padding:22px 17px}.name-row{grid-template-columns:1fr}.apparatus{aspect-ratio:1/1;object-position:center}.hero-actions{margin-top:16px}h1{font-size:3.5rem}.deck{font-size:1rem}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.disc{animation:none!important}}
</style>
</head>
<body>
<section class="mast">
 <div class="hero">
  <div class="eyebrow">The Abbey Bureau of Useful Knowledge · Est. 2005</div>
  <h1>Input Mode<span class="roman">Observatory</span></h1>
  <p class="deck">Does an idea lodge more firmly in your mind when you see it or hear it? Put Jon’s hunch through a small, handsome experiment.</p>
  <img class="apparatus" src="input-mode-observatory.webp" width="1536" height="1024" alt="A painted brass and walnut memory-testing apparatus with a gramophone and twin study stations">
  <div class="hero-actions"><button class="btn" onclick="beginExperiment()">Enter the chamber</button><a class="btn secondary" href="#method">How it works</a></div>
 </div>
</section>
<main>
 <section class="intro" id="method">
  <div><span class="label">The proposition</span><h2>One mind.<br>Two doors.</h2></div>
  <div><p>Jon once wrote that audio and video “sink into my head better than reading.” This observatory gives you one short passage to read and another to hear, then asks the same kind of recall questions after each.</p><div class="rule"></div><p>The order is randomized to reduce the unfair advantage of always doing one mode first. It is a playful personal trial, not neuroscience in a waistcoat.</p></div>
 </section>
 <section class="chamber" id="chamber">
  <div class="progress" aria-label="Experiment progress"><span class="pip on"></span><span class="pip"></span><span class="pip"></span><span class="pip"></span></div>
  <div id="welcome">
   <span class="stepno">Admission ledger</span><h2>Prepare your attention</h2>
   <p>You’ll complete two trials of about ninety seconds. Use headphones if you can, don’t take notes, and answer from memory. The observatory keeps everything in this browser only.</p>
   <div class="name-row"><input id="name" maxlength="30" placeholder="Observer name (optional)" aria-label="Observer name"><button class="btn" onclick="startTrials()">Randomize & begin</button></div>
  </div>
  <div id="trial" class="hidden">
   <span class="stepno" id="trialNumber">Trial one</span><h2 id="trialTitle">Reading aperture</h2>
   <span class="mode-badge"><i></i><span id="modeLabel">Read silently</span></span>
   <p id="instruction"></p>
   <div id="readView" class="passage"></div>
   <div id="listenView" class="listen-box hidden"><div class="disc" id="disc"></div></div>
   <button class="btn" id="exposeBtn" onclick="exposeTrial()">Begin trial</button>
   <button class="btn hidden" id="quizBtn" onclick="showQuiz()">I’m ready for recall</button>
  </div>
  <div id="quiz" class="hidden"><span class="stepno">Recall cabinet</span><h2>What remained?</h2><p>Choose without overthinking. Then record how confident the answer <em>feels</em>.</p><div id="questions"></div><div class="confidence"><label for="confidence">Confidence: <strong id="confidenceText">3 / 5</strong></label><input id="confidence" type="range" min="1" max="5" value="3" oninput="confidenceText.textContent=this.value+' / 5'"></div><button class="btn" onclick="scoreTrial()">Seal my answers</button></div>
  <div id="results" class="hidden"><span class="stepno">The examiner’s report</span><h2 id="resultTitle">Your input signature</h2><div class="result-grid"><div class="meter-card"><h3>Reading recall</h3><div class="score" id="readScore">0/3</div><div class="bar"><span id="readBar"></span></div><p class="tiny" id="readConf"></p></div><div class="meter-card"><h3>Listening recall</h3><div class="score" id="listenScore">0/3</div><div class="bar"><span id="listenBar"></span></div><p class="tiny" id="listenConf"></p></div></div><div class="verdict" id="verdict"></div><p>This is one tiny trial. For a sturdier result, come back another day and see whether the pattern repeats.</p><button class="btn reset" onclick="location.reload()">Run a fresh trial</button></div>
 </section>
 <p class="source">This little chamber was inspired by Jon’s <a href="<?= htmlspecialchars($sourceUrl, ENT_QUOTES) ?>" target="_blank" rel="noopener">33 Christian Classics - MP3 Audio Books (free)</a>, and his knack for noticing how his own mind actually learns.</p>
</main>
<script>
const passages={
 read:{text:`In a small coastal town, the keeper of the clock tower climbed one hundred and twelve steps every Thursday. At the top, she wound three brass gears, polished the blue glass face, and released a paper bird from the eastern window. The bird carried the week’s tide table to the harbour master below.`,questions:[[`How many steps led up the tower?`,`92`,`112`,`120`,`132`,1],[`What colour was the clock face?`,`Amber`,`Green`,`Blue`,`White`,2],[`What did the paper bird carry?`,`A weather warning`,`A letter`,`The tide table`,`A gear`,2]]},
 listen:{text:`Behind the old railway station, a gardener kept seven miniature apple trees in copper pots. Each morning before the first train, he measured their shadows with a red ribbon and wrote the longest one in a green notebook. In autumn, he gave the smallest apple to the station cat, Clementine.`,questions:[[`How many apple trees were there?`,`Five`,`Six`,`Seven`,`Nine`,2],[`What did the gardener use to measure shadows?`,`A brass ruler`,`A red ribbon`,`White string`,`A walking stick`,1],[`What was the station cat called?`,`Clementine`,`Marmalade`,`Beatrice`,`Copper`,0]]}
};
let order=[],trialIndex=0,answers={},scores={read:null,listen:null},conf={read:3,listen:3},hasPlayed=false;
const $=id=>document.getElementById(id);
function setProgress(n){document.querySelectorAll('.pip').forEach((p,i)=>p.classList.toggle('on',i<=n))}
function beginExperiment(){$('chamber').scrollIntoView({behavior:'smooth',block:'center'});$('name').focus()}
function startTrials(){order=Math.random()<.5?['read','listen']:['listen','read'];$('welcome').classList.add('hidden');$('trial').classList.remove('hidden');loadTrial();setProgress(1)}
function loadTrial(){speechSynthesis.cancel();hasPlayed=false;let mode=order[trialIndex],isRead=mode==='read';$('trialNumber').textContent=trialIndex?'Trial two':'Trial one';$('trialTitle').textContent=isRead?'The reading aperture':'The listening horn';$('modeLabel').textContent=isRead?'Read silently':'Listen closely';$('instruction').textContent=isRead?'When you begin, read once at your natural pace. The passage will disappear when you proceed.':'When you begin, the passage will be spoken once. Keep the screen aside and listen for the shape and details.';$('readView').classList.toggle('hidden',!isRead);$('listenView').classList.toggle('hidden',isRead);$('readView').textContent=isRead?passages.read.text:'';$('exposeBtn').classList.remove('hidden');$('quizBtn').classList.add('hidden');$('exposeBtn').textContent=isRead?'Reveal passage':'Play passage';}
function exposeTrial(){let mode=order[trialIndex];$('exposeBtn').classList.add('hidden');$('quizBtn').classList.remove('hidden');if(mode==='listen'){let u=new SpeechSynthesisUtterance(passages.listen.text);u.rate=.88;u.pitch=.92;u.onstart=()=>{$('listenView').classList.add('speaking');$('quizBtn').classList.add('hidden')};u.onend=()=>{$('listenView').classList.remove('speaking');$('quizBtn').classList.remove('hidden');hasPlayed=true};speechSynthesis.speak(u);$('quizBtn').textContent='Audio is playing…'}else{$('quizBtn').textContent='I’m ready for recall'}}
function showQuiz(){speechSynthesis.cancel();$('trial').classList.add('hidden');$('quiz').classList.remove('hidden');$('confidence').value=3;$('confidenceText').textContent='3 / 5';let mode=order[trialIndex];answers={};$('questions').innerHTML=passages[mode].questions.map((q,qi)=>`<div class="question"><strong>${qi+1}. ${q[0]}</strong><div class="options">${q.slice(1,5).map((o,oi)=>`<button class="option" onclick="choose(${qi},${oi},this)">${o}</button>`).join('')}</div></div>`).join('');setProgress(2)}
function choose(q,a,el){answers[q]=a;el.parentElement.querySelectorAll('.option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}
function scoreTrial(){if(Object.keys(answers).length<3){alert('The examiner needs all three answers.');return}let mode=order[trialIndex];scores[mode]=passages[mode].questions.reduce((n,q,i)=>n+(answers[i]===q[5]?1:0),0);conf[mode]=+$('confidence').value;$('quiz').classList.add('hidden');trialIndex++;if(trialIndex<2){$('trial').classList.remove('hidden');loadTrial();setProgress(2)}else showResults()}
function showResults(){setProgress(3);$('results').classList.remove('hidden');let name=$('name').value.trim();$('resultTitle').textContent=(name?name+"’s":'Your')+' input signature';$('readScore').textContent=scores.read+'/3';$('listenScore').textContent=scores.listen+'/3';$('readConf').textContent='Confidence '+conf.read+' / 5';$('listenConf').textContent='Confidence '+conf.listen+' / 5';requestAnimationFrame(()=>{$('readBar').style.width=(scores.read/3*100)+'%';$('listenBar').style.width=(scores.listen/3*100)+'%'});let d=scores.listen-scores.read,v;if(d>=2)v='Your ears won this round decisively. Spoken ideas may give your memory a stronger set of hooks.';else if(d===1)v='Listening has a slight edge today. Audio may indeed slip past the velvet rope more readily.';else if(d<=-2)v='Your eyes carried the day. For precise details, the written page may be your sturdier door.';else if(d===-1)v='Reading has a slight edge today, though one more trial could easily overturn the furniture.';else v='A perfect draw. Your mind appears cheerfully bilingual in page and sound.';$('verdict').textContent=v}
</script>
</body></html>
